// =============================================================================
// BEAT 9 — metrics ribbon (5 value capsules, staggered count-ups)
// =============================================================================
const BeatMetrics: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();
  const base = Math.min(width, height);
  const exit = sceneExit(frame, B.metrics.dur);

  const metrics = [
    { label: "creators", value: 248 },
    { label: "engagement", value: 9.4, suffix: "%" },
    { label: "likes", value: 1820000 },
    { label: "videos", value: 412 },
    { label: "plays", value: 27500000 },
  ];

  const fmtMetric = (m: { value: number; suffix?: string }, n: number) => {
    if (m.suffix) return `${(n / 10).toFixed(1)}${m.suffix}`;
    if (m.value >= 1000000) return `${(n / 1000000).toFixed(1)}M`;
    if (m.value >= 1000) return `${(n / 1000).toFixed(1)}K`;
    return fmt(n);
  };

  return (
    <AbsoluteFill style={{ opacity: exit.opacity, transform: exit.transform }}>
      <div style={{ position: "absolute", left: 0, right: 0, bottom: base * 0.11, display: "flex", justifyContent: "center", gap: base * 0.018 }}>
        {metrics.map((m, i) => {
          const st = staggerChild(i, frame, vfps, { baseDelay: TIMING.entrance, perItem: 16, preset: "SNAPPY", fromY: base * 0.012 });
          const raw = m.suffix ? m.value * 10 : m.value;
          const n = countUp(frame, vfps, raw, TIMING.entrance + i * 16);
          const drift = ambientDrift(frame, 1.6, 100, `metric-${i}`);
          return (
            <div key={m.label} style={{ ...st }}>
              <div style={{ transform: `translateY(${drift}px)` }}>
                <ValueCapsule base={base} value={fmtMetric(m, n)} label={m.label} />
              </div>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

